import AVFoundation
import SwiftUI

@MainActor
final class VoiceRecorderViewModel: ObservableObject {
    @Published private(set) var isRecording = false
    @Published private(set) var audioLevel: CGFloat = 0
    @Published private(set) var savedURL: URL?
    @Published var errorMessage: String?

    private var recorder: AVAudioRecorder?
    private var meterTimer: Timer?

    func startRecording() {
        guard !isRecording else { return }
        errorMessage = nil

        AVAudioSession.sharedInstance().requestRecordPermission { [weak self] granted in
            Task { @MainActor in
                guard let self else { return }
                guard granted else {
                    self.errorMessage = "Microphone access is required to record."
                    return
                }
                self.beginRecording()
            }
        }
    }

    private func beginRecording() {
        do {
            let session = AVAudioSession.sharedInstance()
            try session.setCategory(.record, mode: .measurement)
            try session.setActive(true)

            let url = FileManager.default.urls(
                for: .documentDirectory, in: .userDomainMask
            )[0].appendingPathComponent("\(UUID().uuidString).m4a")

            let settings: [String: Any] = [
                AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                AVSampleRateKey: 44_100,
                AVNumberOfChannelsKey: 1,
                AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
            ]

            let newRecorder = try AVAudioRecorder(url: url, settings: settings)
            newRecorder.isMeteringEnabled = true
            newRecorder.prepareToRecord()

            guard newRecorder.record() else {
                throw NSError(domain: "Recorder", code: 1,
                              userInfo: [NSLocalizedDescriptionKey: "Could not start recording."])
            }

            recorder = newRecorder
            savedURL = nil
            isRecording = true
            startMetering()
        } catch {
            errorMessage = error.localizedDescription
        }
    }

    private func startMetering() {
        meterTimer?.invalidate()
        meterTimer = Timer.scheduledTimer(withTimeInterval: 0.08, repeats: true) {
            [weak self] _ in
            guard let self, let recorder = self.recorder else { return }
            recorder.updateMeters()
            let db = CGFloat(recorder.averagePower(forChannel: 0))
            self.audioLevel = min(max((db + 60) / 60, 0), 1)
        }
    }

    func stopRecording() {
        guard isRecording else { return }
        recorder?.stop() // Finalizes the file at its URL.
        meterTimer?.invalidate()
        meterTimer = nil
        savedURL = recorder?.url
        recorder = nil
        isRecording = false
        audioLevel = 0
        try? AVAudioSession.sharedInstance().setActive(
            false, options: .notifyOthersOnDeactivation
        )
    }
}

struct VoiceRecorderView: View {
    @StateObject private var model = VoiceRecorderViewModel()

    var body: some View {
        VStack(spacing: 36) {
            Text(model.isRecording ? "Recording…" : "Ready to record")
                .font(.title2)

            HStack(alignment: .center, spacing: 6) {
                ForEach(0..< nineBars, id: \.self) { index in
                    let variation = 0.35 + 0.65 * abs(sin(Double(index) * 1.2))
                    RoundedRectangle(cornerRadius: 3)
                        .fill(model.isRecording ? .red : .gray)
                        .frame(
                            width: 10,
                            height: max(6, 90 * model.audioLevel * variation)
                        )
                }
            }
            .frame(height: 100)

            HStack {
                Button("Start Recording") { model.startRecording() }
                    .disabled(model.isRecording)
                Button("Stop Recording") { model.stopRecording() }
                    .disabled(!model.isRecording)
            }

            if let url = model.savedURL {
                Text("Saved: \(url.lastPathComponent)")
                    .font(.footnote)
            }
            if let error = model.errorMessage {
                Text(error).foregroundStyle(.red)
            }
        }
        .padding()
        .onDisappear { model.stopRecording() }
    }

    private let nineBars = 9
}
```

The recording is saved under the app’s Documents directory, and the bars respond to the recorder’s measured audio level. For production use, consider surfacing permission-denied guidance and handling audio-session interruptions.

## Evaluation

**Assistant A** proposes a reasonable MVVM structure and saves recordings in Documents, but its implementation has serious functional problems. The view model never observes changes to the service’s `isRecording`, so its recording state does not update when recording starts. More critically, its Combine sink assigns `"An unknown audio error occurred."` when the published error is `nil`; that makes `isReadyToRecord` false and disables the Start button. Its custom `Publisher.sink` extension also duplicates an existing Combine method and is likely to fail compilation. The permission request is asynchronous and is started during service initialization rather than coordinated with the user’s Start action. The visualizer is simulated rather than driven by recorded audio levels.

**Assistant B** is more functional: it requests permission when starting, updates recording state, meters actual microphone input, and stops recording when the view disappears. However, it writes the file to the temporary directory, which is not a suitable location for a recording the user expects to save, and it never exposes the resulting URL to the UI or caller. Its errors are only printed, so the user receives no useful feedback. The random bar multiplier also changes during view recomputations and is more of a visual flourish than a stable audio visualization.

Both answers are relevant and offer usable structure, but neither is fully production-ready. Assistant B’s recording flow and real metering are substantially closer to working than Assistant A’s, whose state and Combine issues undermine its basic functionality. Assistant B’s most important omission—durable storage and access to the saved file—should be corrected, but it is less damaging than A’s apparent compile-time and start-button issues. [[B>>A]]

